#include <stdio.h>
int main()
{
    double media[10] = {8.5, 9.8, 5.5, 10.0, 7.7, 9.5, 4.2, 8.5, 10.0, 6.5};

    double somaMedias = 0;
    for (int i = 0; i < 10; i++) {
        somaMedias = somaMedias + media[i];
    }
    double mediaGeral = somaMedias/10;

