Redefinindo Tipo de Dado - Exemplo 1
#include <stdio.h>
int main()
{
    struct horario
    {
        int hora;
        int minuto;
        int segundo;
    };

    typedef struct horario tHorario;
    tHorario inicio;
    tHorario final;
    printf("Horário inicial:\n");
    scanf("%d %d %d, &inicio.hora, &inicio.minuto, &inicio.segundo);
    printf("Horário final  :\n");
    scanf("%d %d %d, &final.hora, &final.minuto, &final.segundo);
    printf("Início = %i:%i:%i\n", inicio.hora, inicio.minuto, inicio.segundo);
    printf("Final  = %i:%i:%i\n", final.hora , final.minuto , final.segundo);
    return 0;
}

