Ponteiro para Estrutura
#include <stdio.h>
typedef struct livro
{
char titulo[21];
char autor[21];
int regnum;
double preco;
} tlivro;
int main ()
{
   tlivro lista[2] = { {"C", "Carlos", 102, 70.5}, {"C++", "Alexandre", 321, 63.25} };
   tlivro *ptrl; // ponteiro para estrutura
   ptrl = &lista[0];
   printf("Ponteiro 1   : %X2: %X\n", ptrl, ptrl+1);
   printf("Endereço 1   : %X2: %X\n\n", &lista[0], &lista[1]);
   printf("ptrl->preco  : R$%.2f\n", ptrl->preco);
   printf("(*ptrl).preco: R$%.2f\n\n", (*ptrl).preco);
   printf("ptrl->titulo: %-22s prtl->autor: %-35s\n", ptrl->titulo, ptrl->autor);
   ptrl++; // aponta para a próxima estrutura
   printf("ptrl->titulo: %-22s prtl->autor: %-35s\n", ptrl->titulo, ptrl->autor);
   return 0;
}

