Imprimir Lista Encadeada Com Cabeça
// Versão recursiva
void imprimir(celula *le)
{
    if (le->prox == NULL)
    {
        printf("\n");
        return;
    }
    printf("%d\t", le->prox->conteudo);
    imprimir(le->prox);
}
// Versão iterativa
void imprimir (celula *le) 
{
    celula *p;
    for (p = le->prox; p != NULL; p = p->prox)
    {
        printf ("%d\t", p->conteudo);
    }  
printf ("\n");
}

Verificar se um objeto x pertence a uma lista encadeada, ou seja, se é igual 
ao conteúdo de alguma célula da lista:
11
Busca em Lista Encadeada (Versão Iterativa)
/* Esta função recebe um inteiro x e uma lista encadeada le
   e retorna o endereço da célula que contém x.
   Se o inteiro não for encontrado, retorna NULL. */
celula *buscar(int x, celula *le)
{
    celula *p;
    p = le;
    while (p != NULL && p->conteudo != x)
    {
        p = p->prox;
    }
    return p;
}

Verificar se um objeto x pertence a uma lista encadeada, ou seja, se é igual 
ao conteúdo de alguma célula da lista:
12
Busca em Lista Encadeada (Versão Recursiva)
/* Esta função recebe um inteiro x e uma lista encadeada le
   e retorna o endereço da célula que contém x.
   Se o inteiro não for encontrado, retorna NULL. */
celula *buscar(int x, celula *le)
{
    if (le == NULL)
    {
        return NULL;
    }    
    if (le->conteudo == x)
    {
        return le;
    }
    return buscar(x, le->prox);
}

